#pragma once
#include "../../support.hpp"
namespace algs {
struct TreeType { const std::string name, color, texture; TreeType(std::string name, std::string color, std::string texture): name(std::move(name)), color(std::move(color)), texture(std::move(texture)) {} std::string draw(double x, double y) const { return name + "(" + color + ") at " + text(x) + "," + text(y); } };
class TreeTypeFactory { std::map<std::tuple<std::string, std::string, std::string>, std::shared_ptr<TreeType>> types; public: std::size_t count() const { return types.size(); } std::shared_ptr<TreeType> get(std::string name, std::string color, std::string texture) { auto key = std::make_tuple(name, color, texture); auto& type = types[key]; if (!type) type = std::make_shared<TreeType>(std::move(name), std::move(color), std::move(texture)); return type; } };
class Forest { struct Entry { double x, y; std::shared_ptr<TreeType> type; }; std::vector<Entry> trees; std::shared_ptr<TreeTypeFactory> factory; public: explicit Forest(std::shared_ptr<TreeTypeFactory> factory = std::make_shared<TreeTypeFactory>()): factory(std::move(factory)) {} std::size_t treeCount() const { return trees.size(); } std::size_t typeCount() const { return factory->count(); } Forest& plant(double x, double y, std::string name, std::string color, std::string texture) { trees.push_back({x, y, factory->get(std::move(name), std::move(color), std::move(texture))}); return *this; } std::vector<std::string> draw() const { std::vector<std::string> result; for (auto& tree : trees) result.push_back(tree.type->draw(tree.x, tree.y)); return result; } };
}
